  d.glossary.push(['Run List','Lista de execução','Agrupa fluxos em passos e condições; um Schedule define quando e em quais Agents executar.','controle-runlists'],['Schedule','Agendamento','Configura disparo, recursos e comportamento da execução de uma Run List.','controle-agendamentos'],['Retry','Nova tentativa','Repete um fluxo que falhou conforme a política; pode ter efeitos parciais e precisa de investigação.','controle-repeticoes'],['Audit Log','Registro de auditoria','Eventos da plataforma e alterações; distinto do Activity log de uma execução.','controle-auditoria'],['Retention','Retenção','Políticas que controlam por quanto tempo tipos de evidência permanecem armazenados.','controle-retencao'],['Only Flow','Restaurar a lógica','Recupera a lógica da versão selecionada, preservando os Locators atuais.','controle-restauracao'],['Full Copy','Recuperar em uma cópia','Cria um duplicado da versão selecionada, incluindo Locators, preservando o fluxo atual.','controle-restauracao'],['Full Restore','Restauração completa da versão','Recupera estrutura e Locators da versão selecionada; exige validação contra a aplicação atual.','controle-restauracao']);
